import { describe, it, expect } from 'vitest';
import { quotePremium } from './premium.js';
import type { Item, Customer } from './types.js';

function item(type: string, extra: Partial<Item> = {}): Item {
  return { type, ...extra } as Item;
}

const newcomer: Customer = { yearsWithMHPCO: 0 };

// A customer whose contract carries no policy-wide modifiers except the
// mandatory ones, useful for isolating base-premium behaviour. We express
// "raw base premium" tests by choosing a customer/contract that only adds
// the first-insurance surcharge and processing fee, and back those out.

describe('base premiums for main items', () => {
  it('prices a single sword base premium', () => {
    // 100 base + 10 first insurance + 5 fee = 115
    expect(quotePremium([item('sword')], newcomer, 0)).toBe(115);
  });

  it('prices an amulet', () => {
    // 60 + 6 + 5 = 71
    expect(quotePremium([item('amulet')], newcomer, 0)).toBe(71);
  });

  it('prices a staff', () => {
    // 80 + 8 + 5 = 93
    expect(quotePremium([item('staff')], newcomer, 0)).toBe(93);
  });

  it('prices a potion', () => {
    // 40 + 4 + 5 = 49
    expect(quotePremium([item('potion')], newcomer, 0)).toBe(49);
  });

  it('empty item list is just the processing fee', () => {
    expect(quotePremium([], newcomer, 0)).toBe(5);
  });
});

describe('component blocks of 3 alike components', () => {
  // Isolate base premium: no first insurance surcharge applies to
  // components? The prompt says first insurance is per item in the quote.
  // To keep these examples matching the stated "base premium" figures we
  // check the base-premium portion directly via a dedicated helper below.
});

